insert into public.post_likes (post_id, user_id, created_at)
select post.id, liker.id, post.created_at + interval '3 hours'
from public.posts as post
join public.profiles as liker on liker.id <> post.user_id
where ('x' || substr(md5(post.id::text || liker.username), 1, 8))
      ::bit(32)::bigint % 26 = 0
on conflict do nothing;

insert into public.comments (post_id, user_id, body, created_at)
select post.id, author.id, phrase.body,
       post.created_at + interval '7 hours'
from public.posts as post
join public.profiles as author on author.id <> post.user_id
cross join lateral (
  select body from (values
    ('Adding this to my list right now.'),
    ('Went last month, completely agree.'),
    ('Try the north entrance, way quieter.'),
    ('How long did you spend here?'),
    ('This is the one I keep meaning to get to.'),
    ('Bold rating. I would have gone higher.'),
    ('Was it busy when you went?'),
    ('Finally someone rates this properly.'),
    ('Did you do the tour or just walk around?'),
    ('Been three times, still not tired of it.'),
    ('Underrated, thank you for posting.'),
    ('I had the opposite experience honestly.'),
    ('Weekday or weekend? Makes a big difference here.'),
    ('Okay you have convinced me.'),
    ('Great shot, what time of day was that?'),
    ('This has been on my list for two years.'),
    ('Agreed on the crowds. Go at opening.'),
    ('Did you pay full price or find a discount day?')
  ) as options(body)
  offset (('x' || substr(md5(post.id::text || author.username), 9, 8))
          ::bit(32)::bigint % 18)
  limit 1
) as phrase
where ('x' || substr(md5(post.id::text || author.username), 17, 8))
      ::bit(32)::bigint % 55 = 0;

